def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    if AVG == 0:
        avg_diff = CUR  # Treat empty stacks as having AVG = 0, so proximity to CUR is directly CUR
    else:
        avg_diff = abs(AVG - CUR)

    # Density factor: penalizes stacks with more concentrated retrieval IDs
    if AVG == 0:
        density_penalty = 0  # Prevent division by zero for empty stacks
    else:
        density_penalty = 1 / (AVG + 1)

    # Proximity factor: lower is better, but scaled by density to account for spread
    proximity = avg_diff * density_penalty

    # Disruption factor: higher if more containers are blocked by the current one
    disruption = RI / (SH + 1) if SH + 1 > 0 else 0

    # Future congestion prediction: stacks with high average IDs may block more in the future
    if CUR == 0:
        future_congestion = 0
    else:
        future_congestion = AVG / (CUR + 1)

    # Temporal alignment: rewards stacks where the current container aligns with the average ID
    # to reduce future blocking by aligning with the flow of retrieval
    if CUR == 0:
        temporal_alignment = 0
    else:
        temp_diff = abs(AVG - CUR)
        temporal_alignment = 1 - (temp_diff / (CUR + 1))

    # Structural relevance: proportion of the stack that will not be blocked by the newly placed container
    structural_relevance = (SH - RI) / (SH + 1) if SH + 1 > 0 else 0

    # Estimate future dispersion for stacks that may block containers in the future
    if avg_diff == 0:
        retrieval_dispersion = 1.0
    else:
        retrieval_dispersion = abs(AVG - CUR) / (SH + 1)

    priority = proximity + disruption + future_congestion * (1 - structural_relevance) + temporal_alignment * structural_relevance + retrieval_dispersion * (1 - disruption)

    return priority

